import{_ as a,o as e,c as d,ai as r}from"./chunks/framework.ampVZV4B.js";const g=JSON.parse('{"title":"Java · 01 语言基础","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/java/01-basics.md","filePath":"tech-system/backend/java/01-basics.md"}'),o={name:"tech-system/backend/java/01-basics.md"};function l(i,t,n,s,h,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="java-·-01-语言基础" tabindex="-1">Java · 01 语言基础 <a class="header-anchor" href="#java-·-01-语言基础" aria-label="Permalink to “Java · 01 语言基础”">​</a></h1><blockquote><p>语法、类型、集合、函数——服务交付与协作，不是语法百科。面试细题见 <a href="/my-vitepress-site/java/base-overview.html">就业指南 · Java</a>。</p></blockquote><h2 id="_1-定位-java-卖什么" tabindex="-1">1. 定位：Java 卖什么 <a class="header-anchor" href="#_1-定位-java-卖什么" aria-label="Permalink to “1. 定位：Java 卖什么”">​</a></h2><p>Java 卖的是 <strong>可控与存量</strong>：</p><ul><li><strong>静态类型 + 编译期检查</strong>：大项目改起来相对敢下手</li><li><strong>工程型语言</strong>：强调可维护、可协作，而不是写起来最短</li><li><strong>生态绑死企业场景</strong>：ORM、中间件、监控、招聘市场都围绕它转</li><li><strong>「慢热」</strong>：启动和样板代码有成本，换来的是长期可预期</li></ul><p>一句话：Java 不是爽感语言，是 <strong>长期系统的默认承重墙</strong>。</p><h3 id="和本站其它语言的分工" tabindex="-1">和本站其它语言的分工 <a class="header-anchor" href="#和本站其它语言的分工" aria-label="Permalink to “和本站其它语言的分工”">​</a></h3><table tabindex="0"><thead><tr><th>语言</th><th>角色</th><th>什么时候上</th></tr></thead><tbody><tr><td><strong>Java</strong></td><td>主业务、库表权威、事务与权限</td><td>默认</td></tr><tr><td>Python</td><td>AI / 脚本 / 胶水</td><td>模型与批处理</td></tr><tr><td>Node(TS)</td><td>BFF / Electron 本地服务</td><td>靠近前端与桌面</td></tr><tr><td>Go</td><td>边车、小高并发工具</td><td>补位</td></tr><tr><td>C#</td><td>Windows / .NET 存量</td><td>撞上再学</td></tr></tbody></table><hr><h2 id="_2-类型系统-怎么用才省事" tabindex="-1">2. 类型系统：怎么用才省事 <a class="header-anchor" href="#_2-类型系统-怎么用才省事" aria-label="Permalink to “2. 类型系统：怎么用才省事”">​</a></h2><h3 id="该坚持的" tabindex="-1">该坚持的 <a class="header-anchor" href="#该坚持的" aria-label="Permalink to “该坚持的”">​</a></h3><ul><li><strong>业务入参出参用明确类型</strong>，少用裸 <code>Map&lt;String, Object&gt;</code> 当领域模型</li><li><strong>集合声明用接口类型</strong>：<code>List</code> / <code>Map</code>，实现类留给创建处</li><li><strong>空值策略统一</strong>：要么 Optional 用在返回值边界，要么约定「禁止 null + 校验」，团队内二选一</li></ul><h3 id="现代语法-java-8-我怎么用" tabindex="-1">现代语法（Java 8+）我怎么用 <a class="header-anchor" href="#现代语法-java-8-我怎么用" aria-label="Permalink to “现代语法（Java 8+）我怎么用”">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>我会用</th><th>我会克制</th></tr></thead><tbody><tr><td>Lambda / 方法引用</td><td>回调、集合短变换</td><td>嵌套三层看不懂的写法</td></tr><tr><td>Stream</td><td>filter/map/collect</td><td>热点路径里无意义的多次中间集合</td></tr><tr><td>Optional</td><td>方法返回「可能没有」</td><td>字段到处 Optional、<code>get()</code> 乱飞</td></tr><tr><td><code>var</code></td><td>右边类型已经很明显时</td><td>公共 API 签名里炫技</td></tr><tr><td>record（新版本）</td><td>不可变 DTO / 事件</td><td>强行替代一切实体</td></tr></tbody></table><h3 id="异常" tabindex="-1">异常 <a class="header-anchor" href="#异常" aria-label="Permalink to “异常”">​</a></h3><ul><li><strong>受检异常</strong>有历史包袱：边界转换成业务错误码 / 运行时异常，避免 <code>throws Exception</code> 污染整条调用链</li><li><strong>业务可预期失败</strong>（库存不足、状态不允许）用明确错误模型，不要全靠异常控制流程</li><li><strong>真正异常</strong>（下游超时、磁盘满）打日志 + 可观测，必要时熔断降级</li></ul><hr><h2 id="_3-集合与常用-api" tabindex="-1">3. 集合与常用 API <a class="header-anchor" href="#_3-集合与常用-api" aria-label="Permalink to “3. 集合与常用 API”">​</a></h2><h3 id="选型直觉" tabindex="-1">选型直觉 <a class="header-anchor" href="#选型直觉" aria-label="Permalink to “选型直觉”">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>常用选择</th><th>注意</th></tr></thead><tbody><tr><td>有序列表</td><td><code>ArrayList</code></td><td>随机访问快；中间插入多再考虑 LinkedList（实际很少）</td></tr><tr><td>去重 / 存在判断</td><td><code>HashSet</code></td><td>元素要正确实现 equals/hashCode</td></tr><tr><td>键值</td><td><code>HashMap</code></td><td>单线程默认；并发读多写少 → <code>ConcurrentHashMap</code></td></tr><tr><td>有序键</td><td><code>TreeMap</code> / <code>LinkedHashMap</code></td><td>排序成本 vs 插入序</td></tr><tr><td>队列</td><td><code>ArrayBlockingQueue</code> 等</td><td>线程池、异步任务背压</td></tr></tbody></table><h3 id="equals-hashcode" tabindex="-1">equals / hashCode <a class="header-anchor" href="#equals-hashcode" aria-label="Permalink to “equals / hashCode”">​</a></h3><p>实体进 <code>Set</code> / 当 <code>Map</code> key 时必须成对正确；只改业务字段、用 IDE 生成或用业务主键策略，避免「明明同一个单号却去重失败」。</p><h3 id="函数式接口" tabindex="-1">函数式接口 <a class="header-anchor" href="#函数式接口" aria-label="Permalink to “函数式接口”">​</a></h3><p><code>Function</code> / <code>Predicate</code> / <code>Consumer</code> / <code>Supplier</code> 让回调短。原则：<strong>可读性优先</strong>——同事 10 秒看不懂的一行 Stream，不如三行 for。</p><hr><h2 id="_4-面向对象-交付里真正有用的部分" tabindex="-1">4. 面向对象：交付里真正有用的部分 <a class="header-anchor" href="#_4-面向对象-交付里真正有用的部分" aria-label="Permalink to “4. 面向对象：交付里真正有用的部分”">​</a></h2><ul><li><strong>封装边界</strong>：Controller 薄、Service 承载用例、基础设施向外适配</li><li><strong>组合优于深层继承</strong>：业务差异用策略 / 多态，少造七层基类</li><li><strong>接口面向能力</strong>：<code>PaymentGateway</code> 而不是绑死某 SDK 类名</li></ul><p>八股式「三大特性」能答；落地更看 <strong>模块怎么切、依赖怎么指</strong>。</p><hr><h2 id="_5-我为什么仍把-java-当主栈" tabindex="-1">5. 我为什么仍把 Java 当主栈 <a class="header-anchor" href="#_5-我为什么仍把-java-当主栈" aria-label="Permalink to “5. 我为什么仍把 Java 当主栈”">​</a></h2><ol><li>ToB / 工业 / CRM 类交付，招聘与中间件默认就是它</li><li>静态类型在多人、多月项目上更敢改</li><li>和 Spring 绑在一起后，<strong>批量交业务</strong>的路径最熟</li><li>AI 来了也不换墙：Java 管状态与配额，Python 管模型试错</li></ol><p>下一篇：<a href="./02-core.html">02 核心能力</a>（JVM、并发、内存——语言真正不同的地方）</p>',32)])])}const p=a(o,[["render",l]]);export{g as __pageData,p as default};
